70	// Spec: an item's base premium is 10 % of its insurance value.
71	// Integer division (not * 0.1) keeps gold amounts exact.
72	const VALUE_TO_PREMIUM_RATIO = 10;
73	
74	const basePremiumOf = (itemType: string): number =>
75	  INSURANCE_VALUES[itemType] / VALUE_TO_PREMIUM_RATIO;
76	
77	const BLOCK_SIZE = 3;
78	const COMPONENT_BLOCK_PREMIUM = 60;
79	
80	const COMPONENT_TYPES = ["rune", "moonstone"];
81	
82	const componentBlockAdjustment = (
83	  items: Item[],
84	  componentType: string,
85	): number => {
86	  const count = items.filter((item) => item.type === componentType).length;
87	  return count === BLOCK_SIZE
88	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * basePremiumOf(componentType)
89	    : 0;
90	};
91	
92	const basePremiumFor = (items: Item[]): number =>
93	  items.reduce((total, item) => total + basePremiumOf(item.type), 0) +
94	  COMPONENT_TYPES.reduce(
95	    (total, componentType) => total + componentBlockAdjustment(items, componentType),
96	    0,
97	  );
98	
99	const surchargeFor = (
100	  items: Item[],
101	  rate: number,
102	  applies: (item: Item) => boolean,
103	): number =>
104	  items.reduce(
105	    (total, item) =>
106	      total + (applies(item) ? rate * basePremiumOf(item.type) : 0),
107	    0,
108	  );
109	
110	const isCursed = (item: Item): boolean => item.cursed === true;
111	
112	const isHighlyEnchanted = (item: Item): boolean =>
113	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
114	
115	const curseSurchargeFor = (items: Item[]): number =>
116	  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);
117	
118	const highEnchantmentSurchargeFor = (items: Item[]): number =>
119	  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
120	
121	const quotePremium = (
122	  items: Item[],
123	  customer: Customer,
124	  isFollowUpContract: boolean,
125	): number => {
126	  const basePremium = basePremiumFor(items);
127	  const itemSurcharges =
128	    curseSurchargeFor(items) + highEnchantmentSurchargeFor(items);
129	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
130	  const loyaltyDiscount =
131	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
132	      ? basePremium * LOYALTY_DISCOUNT_RATE
133	      : 0;
134	  const followUpDiscount = isFollowUpContract
135	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
136	    : 0;
137	  return Math.ceil(
138	    basePremium +
139	      itemSurcharges +
140	      firstInsuranceSurcharge -
141	      loyaltyDiscount -
142	      followUpDiscount +
143	      PROCESSING_FEE,
144	  );
145	};
