147	const DEDUCTIBLE_PER_DAMAGE = 100;
148	const PAYOUT_CAP_MULTIPLIER = 2;
149	
150	const claimResult = (
151	  claimStep: ClaimStep,
152	  policyItems: Item[],
153	): ClaimResult => {
154	  const payout = claimStep.incident.damages.reduce((total, damage) => {
155	    const damagedItem = policyItems.find(
156	      (item) => item.type === damage.itemType,
157	    );
158	    const reimbursed =
159	      (damagedItem?.enchantment ?? 0) >= 8
160	        ? damage.amount * 0.5
161	        : damage.amount;
162	    return total + (reimbursed - DEDUCTIBLE_PER_DAMAGE);
163	  }, 0);
164	  const insuranceSum = policyItems.reduce(
165	    (total, item) => total + INSURANCE_VALUES[item.type],
166	    0,
167	  );
168	  const cap = PAYOUT_CAP_MULTIPLIER * insuranceSum;
169	  return { payout, remainingCap: cap - payout };
170	};
