172	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
173	  results: scenario.steps.map((step, index) => {
174	    if (step.op === "claim") {
175	      const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
176	      return claimResult(step, policyItems);
177	    }
178	    return {
179	      premium: quotePremium(step.items, scenario.customer, index > 0),
180	    };
181	  }),
182	});
